from flask import Flask, request, jsonify, g
from pymongo import MongoClient
import json
import re

app = Flask(__name__)
client = MongoClient('mongodb://app_user:password@localhost:27017/multitenant')
db = client.multitenant

def get_tenant_id():
    """Extract tenant from JWT - simplified for demo"""
    auth_header = request.headers.get('X-Tenant-ID', '')
    # Basic validation - alphanumeric only
    if not re.match(r'^[a-zA-Z0-9_-]+$', auth_header):
        return None
    return auth_header

@app.before_request
def set_tenant_context():
    g.tenant_id = get_tenant_id()
    if not g.tenant_id and request.endpoint not in ('health',):
        return jsonify({'error': 'Missing tenant context'}), 401

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/documents/search', methods=['POST'])
def search_documents():
    """Search documents with flexible query support"""
    tenant_id = g.tenant_id
    body = request.get_json(force=True)

    # Build query from user input
    query = {}

    # Add tenant filter
    query['tenant_id'] = tenant_id

    # Support flexible field searches
    if 'filters' in body:
        filters = body['filters']
        if isinstance(filters, dict):
            for field, value in filters.items():
                # Prevent querying across tenants directly
                if field == 'tenant_id':
                    continue
                # Allow nested query operators for advanced search
                query[field] = value

    # Support text search
    if 'text_query' in body:
        query['$text'] = {'$search': body['text_query']}

    # Sort support
    sort_field = body.get('sort', 'created_at')
    sort_dir = -1 if body.get('sort_desc', True) else 1

    try:
        results = list(
            db.documents.find(query, {'_id': 0})
            .sort(sort_field, sort_dir)
            .limit(50)
        )
        return jsonify({'results': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 400

@app.route('/api/documents', methods=['POST'])
def create_document():
    """Create a new document"""
    tenant_id = g.tenant_id
    body = request.get_json(force=True)

    doc = {
        'tenant_id': tenant_id,
        'title': body.get('title', ''),
        'content': body.get('content', ''),
        'tags': body.get('tags', []),
        'metadata': body.get('metadata', {}),
        'status': 'active'
    }

    db.documents.insert_one(doc)
    return jsonify({'status': 'created'}), 201

@app.route('/api/documents/<doc_id>', methods=['DELETE'])
def delete_document(doc_id):
    """Delete a document by ID"""
    tenant_id = g.tenant_id
    result = db.documents.delete_one({
        'doc_id': doc_id,
        'tenant_id': tenant_id
    })
    if result.deleted_count == 0:
        return jsonify({'error': 'Not found'}), 404
    return jsonify({'status': 'deleted'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
